// Define o contrato de entrada e parâmetros do pipeline
return [{
  json: {
    contrato_id: "CTR-2026-N8N-001",
    solicitante: "Auditoria e Governança Corporativa",
    texto_contrato: `CONTRATO DE PRESTAÇÃO DE SERVIÇOS DE DESENVOLVIMENTO DE INTELIGÊNCIA ARTIFICIAL

CONTRATANTE: TechSolutions Ltda., inscrita no CNPJ sob o nº 12.345.678/0001-90, com sede na Av. Paulista, 1000, São Paulo/SP.

CONTRATADA: Alfa Consultoria em IA S.A., inscrita no CNPJ sob o nº 98.765.432/0001-10, com sede no Rio de Janeiro/RJ.

CLÁUSULA PRIMEIRA - DO OBJETO
O presente instrumento tem por objeto a prestação de serviços técnicos especializados de desenvolvimento, integração e suporte de agentes inteligentes autônomos para análise contratual.

CLÁUSULA SEGUNDA - DO VALOR E FORMA DE PAGAMENTO
Pela prestação dos serviços, a CONTRATANTE pagará à CONTRATADA o valor global de R$ 120.000,00 (cento e vinte mil reais), dividido em 12 (doze) parcelas mensais e sucessivas de R$ 10.000,00 (dez mil reais).

CLÁUSULA TERCEIRA - DA VIGÊNCIA
O prazo de vigência deste contrato é de 12 (doze) meses, iniciando-se em 15 de janeiro de 2026 e encerrando-se em 15 de janeiro de 2027. O contrato poderá ser rescindido antecipadamente mediante aviso prévio por escrito de 30 (trinta) dias.

CLÁUSULA QUARTA - DA RESCISÃO E MULTA
Em caso de rescisão imotivada por iniciativa de qualquer das partes antes do término do prazo estipulado, a parte que der causa incorrerá em multa compensatória de 20% (vinte por cento) sobre o saldo remanescente do contrato.`
  }
}];

// Extração incompleta ou inválida: gera log de exceção sem acionar Agente 2
return [{
  json: {
    status_pipeline: "BLOQUEADO_EXTRACAO_INVALIDA",
    motivo: "Contrato não possui valor financeiro calculável ou cláusulas mínimas extraídas.",
    dados_parciais: $json
  }
}];

// Consolida o Dossiê Final de Análise Contratual a partir dos outputs dos Agentes 1 e 2
const resultadoAgente1 = $('Agente 1: Consultar GET /status').item.json;
const resultadoAgente2 = $('Agente 2: Consultar GET /status').item.json;

const extracao = resultadoAgente1.data || {};
const auditoria = resultadoAgente2.data || {};

// Determina a recomendação executiva de governança
let decisaoGovernança = "APROVADO_DIRETORIA";
if (auditoria.nivel_risco_geral === "ALTO" || (auditoria.itens_nao_conformes && auditoria.itens_nao_conformes > 0)) {
  decisaoGovernança = "BLOQUEADO_REVISAO_JURIDICA_OBRIGATORIA";
} else if (auditoria.nivel_risco_geral === "BAIXO") {
  decisaoGovernança = "APROVADO_SUMARIAMENTE";
}

return [{
  json: {
    metadata_pipeline: {
      orquestrador: "n8n Workflow Engine v1.x/v2.x",
      ciclo: "Assíncrono Completo com Polling e Roteamento de Risco",
      timestamp_conclusao: new Date().toISOString(),
      agente_extracao: {
        task_id: resultadoAgente1.task_id,
        status: resultadoAgente1.status,
        tempo_execucao_s: resultadoAgente1.completed_at ? (resultadoAgente1.completed_at - resultadoAgente1.created_at).toFixed(2) : null
      },
      agente_auditoria: {
        task_id: resultadoAgente2.task_id,
        status: resultadoAgente2.status,
        tempo_execucao_s: resultadoAgente2.completed_at ? (resultadoAgente2.completed_at - resultadoAgente2.created_at).toFixed(2) : null
      }
    },
    contrato: {
      titulo: extracao.titulo,
      partes: {
        contratante: extracao.contratante,
        contratada: extracao.contratada
      },
      objeto: extracao.objeto,
      financeiro: extracao.financeiro,
      vigencia: extracao.vigencia,
      penalidades: extracao.penalidades,
      fornecedor_homologado: extracao.fornecedor_homologado
    },
    auditoria_conformidade: {
      score_conformidade: auditoria.score_conformidade,
      nivel_risco_geral: auditoria.nivel_risco_geral,
      itens_auditados: auditoria.itens_auditados,
      total_regras_auditadas: auditoria.total_regras_auditadas,
      itens_conformes: auditoria.itens_conformes,
      itens_alerta: auditoria.itens_alerta,
      itens_nao_conformes: auditoria.itens_nao_conformes,
      recomendacoes_mitigacao: auditoria.recomendacoes_mitigacao,
      parecer_executivo_markdown: auditoria.parecer_executivo_markdown
    },
    decisao_governanca: decisaoGovernança
  }
}];

return JSON.stringify({
  politica_codigo: 'POL-COMPLIANCE-2026-V2',
  limite_alcada_gerencial_brl: 100000.0,
  limite_teto_multa_recomendado_percentual: 10.0,
  limite_teto_multa_critico_percentual: 20.0,
  aviso_previo_minimo_dias: 30,
  aviso_previo_recomendado_servicos_criticos_dias: 45,
  exige_ratificacao_diretoria_se_risco_medio_alto: true,
  score_minimo_homologacao_fornecedor: 80.0
});

// Entrega o dossiê executivo final com a deliberação do AI Agent
const dossie = $('Consolidar Dossiê Contratual Final').item.json;
const sinteseIA = $('AI Agent de Governança Estratégica').item.json;

return [{
  json: {
    status_pipeline: "FINALIZADO_COM_SUCESSO",
    orquestrador: "n8n Multi-Agent Workflow Engine",
    dossie_tecnico: dossie,
    deliberacao_executiva_ia: sinteseIA.output || sinteseIA.text || sinteseIA,
    homologado_em: new Date().toISOString()
  }
}];
